//! The test harness (rustc's `--test`, libtest): runs the `#[test]`
//! functions collected by the compiler and reports like libtest does with
//! one test thread.

use crate::string::String;
use crate::sync::{Arc, Mutex};
use crate::vec::Vec;

/// How a test is expected to panic.
pub enum ShouldPanic {
    No,
    Yes,
    YesWithMessage(&'static str),
}

/// A test function generated by the compiler.
pub struct TestDesc {
    pub name: &'static str,
    pub ignore: bool,
    pub ignore_message: Option<&'static str>,
    pub should_panic: ShouldPanic,
    pub file: &'static str,
    pub line: u32,
    pub col: u32,
    pub func: fn() -> Result<(), String>,
}

/// Converts a test function's result (`()` or `Result<(), E>`) into the
/// harness outcome.
pub fn assert_test_result<T: crate::process::Termination>(result: T) -> Result<(), String> {
    let code = result.report().to_i32();
    if code == 0 {
        Ok(())
    } else {
        Err(crate::format!(
            "the test returned a termination value with a non-zero status code ({}) which indicates a failure",
            code
        ))
    }
}

struct Opts {
    filters: Vec<String>,
    skips: Vec<String>,
    exact: bool,
    ignored: bool,
    include_ignored: bool,
    nocapture: bool,
    list: bool,
}

fn parse_args() -> Opts {
    let mut o = Opts {
        filters: Vec::new(),
        skips: Vec::new(),
        exact: false,
        ignored: false,
        include_ignored: false,
        nocapture: crate::env::var("RUST_TEST_NOCAPTURE").map(|v| v != "0").unwrap_or(false),
        list: false,
    };
    let args: Vec<String> = crate::env::args().skip(1).collect();
    let mut i = 0;
    while i < args.len() {
        let a = args[i].as_str();
        match a {
            "--exact" => o.exact = true,
            "--ignored" => o.ignored = true,
            "--include-ignored" => o.include_ignored = true,
            "--nocapture" | "--no-capture" => o.nocapture = true,
            "--list" => o.list = true,
            "--test-threads" | "--color" | "--format" | "-Z" | "--logfile" | "--shuffle-seed" => i += 1,
            "--skip" => {
                if i + 1 < args.len() {
                    o.skips.push(args[i + 1].clone());
                }
                i += 1;
            }
            _ => {
                if !a.starts_with('-') {
                    o.filters.push(String::from(a));
                }
            }
        }
        i += 1;
    }
    o
}

fn matches(o: &Opts, name: &str) -> bool {
    if !o.filters.is_empty() {
        let hit = o.filters.iter().any(|f| if o.exact { name == f.as_str() } else { name.contains(f.as_str()) });
        if !hit {
            return false;
        }
    }
    !o.skips.iter().any(|s| if o.exact { name == s.as_str() } else { name.contains(s.as_str()) })
}

fn panic_message(p: &(dyn crate::any::Any + Send)) -> Option<String> {
    if let Some(s) = p.downcast_ref::<&'static str>() {
        return Some(String::from(*s));
    }
    p.downcast_ref::<String>().cloned()
}

/// Runs the tests (the generated `main` of a `--test` build).
pub fn test_main_static(tests: &[TestDesc]) {
    let o = parse_args();
    let mut order: Vec<&TestDesc> = tests.iter().collect();
    order.sort_by(|a, b| a.name.cmp(b.name));
    let total = order.len();
    let run: Vec<&TestDesc> = order.into_iter().filter(|t| matches(&o, t.name)).filter(|t| !o.ignored || t.ignore).collect();
    let filtered = total - run.len();
    if o.list {
        for t in &run {
            crate::println!("{}: test", t.name);
        }
        crate::println!();
        crate::println!("{} test{}, 0 benchmarks", run.len(), if run.len() == 1 { "" } else { "s" });
        return;
    }
    let start = crate::time::Instant::now();
    crate::println!();
    crate::println!("running {} test{}", run.len(), if run.len() == 1 { "" } else { "s" });
    let (mut passed, mut failed, mut ignored) = (0usize, 0usize, 0usize);
    let mut failures: Vec<(&'static str, Vec<u8>)> = Vec::new();
    for t in run {
        if t.ignore && !o.ignored && !o.include_ignored {
            match t.ignore_message {
                Some(m) => crate::println!("test {} ... ignored, {}", t.name, m),
                None => crate::println!("test {} ... ignored", t.name),
            }
            ignored += 1;
            continue;
        }
        let sp = match t.should_panic {
            ShouldPanic::No => "",
            _ => " - should panic",
        };
        let sink: Arc<Mutex<Vec<u8>>> = Arc::new(Mutex::new(Vec::new()));
        let sink2 = sink.clone();
        let nocapture = o.nocapture;
        let f = t.func;
        let h = crate::thread::Builder::new()
            .name(String::from(t.name))
            .spawn(move || {
                if !nocapture {
                    crate::io::set_output_capture(Some(sink2));
                }
                f()
            })
            .unwrap();
        let res = h.join();
        let mut out = match sink.lock() {
            Ok(g) => g.clone(),
            Err(e) => e.into_inner().clone(),
        };
        let mut note: Option<String> = None;
        let ok = match (res, &t.should_panic) {
            (Ok(Ok(())), ShouldPanic::No) => true,
            (Ok(Err(_)), ShouldPanic::No) => false,
            (Ok(_), _) => {
                note = Some(crate::format!("test did not panic as expected at {}:{}:{}", t.file, t.line, t.col));
                false
            }
            (Err(_), ShouldPanic::No) => false,
            (Err(_), ShouldPanic::Yes) => true,
            (Err(p), ShouldPanic::YesWithMessage(exp)) => match panic_message(&*p) {
                Some(m) if m.contains(exp) => true,
                Some(m) => {
                    note = Some(crate::format!(
                        "panic did not contain expected string\n      panic message: {:?}\n expected substring: {:?}",
                        m, exp
                    ));
                    false
                }
                None => {
                    note = Some(crate::format!(
                        "expected panic with string value,\n found non-string value: `{:?}`\n     expected substring: {:?}",
                        (*p).type_id(),
                        exp
                    ));
                    false
                }
            },
        };
        if ok {
            crate::println!("test {}{} ... ok", t.name, sp);
            passed += 1;
        } else {
            crate::println!("test {}{} ... FAILED", t.name, sp);
            failed += 1;
            if let Some(n) = note {
                out.extend_from_slice(b"note: ");
                out.extend_from_slice(n.as_bytes());
            }
            failures.push((t.name, out));
        }
    }
    let elapsed = start.elapsed().as_secs_f64();
    if !failures.is_empty() {
        crate::println!();
        crate::println!("failures:");
        crate::println!();
        for (name, out) in &failures {
            if out.is_empty() {
                continue;
            }
            crate::println!("---- {} stdout ----", name);
            crate::print!("{}", String::from_utf8_lossy(out));
            crate::println!();
        }
        crate::println!();
        crate::println!("failures:");
        for (name, _) in &failures {
            crate::println!("    {}", name);
        }
    }
    crate::println!();
    crate::println!(
        "test result: {}. {} passed; {} failed; {} ignored; 0 measured; {} filtered out; finished in {:.2}s",
        if failed == 0 { "ok" } else { "FAILED" },
        passed,
        failed,
        ignored,
        filtered,
        elapsed
    );
    crate::println!();
    if failed != 0 {
        crate::process::exit(101);
    }
}
